// Package demo ships a small, self-contained library so Nuvio is useful the
// moment it is installed. Artwork is generated by the art package and every
// item plays the same CC-BY Blender Foundation trailer.
package demo

import (
	"crypto/md5"
	"embed"
	"encoding/hex"
	"fmt"
	"strings"
	"time"

	"nuvio/internal/media"
	"nuvio/internal/model"
)

//go:embed assets/sample.mp4 assets/zh.vtt assets/en.vtt
var assets embed.FS

// Library ids are stable so clients can cache them.
var (
	MovieLibraryID = id("library:demo:movies")
	ShowLibraryID  = id("library:demo:shows")
)

var sampleBytes []byte
var sampleDuration int64

func init() {
	sampleBytes, _ = assets.ReadFile("assets/sample.mp4")
	sampleDuration = media.DurationBytes(sampleBytes)
}

// SampleBytes returns the embedded trailer.
func SampleBytes() []byte { return sampleBytes }

// SampleDurationTicks is the real duration of the demo clip.
func SampleDurationTicks() int64 { return sampleDuration }

// SubtitleBytes resolves a demo subtitle URL such as demo://subs/zh.vtt.
func SubtitleBytes(path string) ([]byte, bool) {
	name := strings.TrimPrefix(path, "demo://subs/")
	if name == path {
		return nil, false
	}
	b, err := assets.ReadFile("assets/" + name)
	return b, err == nil
}

// Libraries returns the two demo libraries.
func Libraries() []*model.Library {
	return []*model.Library{
		{
			ID:      MovieLibraryID,
			Name:    "Movies",
			Type:    model.LibraryMovies,
			Paths:   []string{},
			Demo:    true,
			AddedAt: time.Now().Add(-time.Hour * 24 * 30),
		},
		{
			ID:      ShowLibraryID,
			Name:    "Shows",
			Type:    model.LibraryShows,
			Paths:   []string{},
			Demo:    true,
			AddedAt: time.Now().Add(-time.Hour * 24 * 29),
		},
	}
}

func mediaInfo() *model.MediaInfo {
	secs := float64(sampleDuration) / 10_000_000
	bitrate := int64(0)
	if secs > 0 {
		bitrate = int64(float64(len(sampleBytes)) * 8 / secs)
	}
	return &model.MediaInfo{
		Container:     "mp4",
		DurationTicks: sampleDuration,
		Size:          int64(len(sampleBytes)),
		Bitrate:       bitrate,
		VideoCodec:    "h264",
		AudioCodec:    "aac",
		Width:         854,
		Height:        480,
		AudioChannels: 2,
		AudioTracks: []model.AudioTrack{
			{Index: 1, Language: "en", Title: "English", Codec: "aac", Channels: 2, Default: true},
		},
		Subtitles: []model.Subtitle{
			{Index: 2, Language: "zh", Title: "Chinese (Simplified)", Codec: "vtt", Path: "demo://subs/zh.vtt", Default: true},
			{Index: 3, Language: "en", Title: "English", Codec: "vtt", Path: "demo://subs/en.vtt"},
		},
	}
}

