// Items builds the complete demo catalog.
func Items() []*model.Item {
	now := time.Now().UTC()
	items := make([]*model.Item, 0, 64)

	for i, m := range movies {
		mi := mediaInfo()
		added := now.Add(-time.Duration(i*17+3) * time.Hour)
		it := &model.Item{
			ID:             id("demo:movie:" + m.key),
			Type:           model.TypeMovie,
			Name:           m.title,
			SortName:       m.title,
			Overview:       m.overview,
			Taglines:       []string{m.tagline},
			Year:           m.year,
			PremiereDate:   fmt.Sprintf("%d-03-01T00:00:00.0000000Z", m.year),
			Rating:         m.rating,
			OfficialRating: "PG-13",
			RuntimeTicks:   int64(m.minutes) * 60 * 10_000_000,
			Genres:         m.genres,
			LibraryID:      MovieLibraryID,
			ParentID:       MovieLibraryID,
			Path:           "demo://sample",
			Container:      "mp4",
			Size:           int64(len(sampleBytes)),
			AddedAt:        added,
			Media:          mi,
			ArtSeed:        "demo:" + m.key,
			Demo:           true,
		}
		items = append(items, it)
	}

	for si, sd := range series {
		seriesID := id("demo:series:" + sd.key)
		seriesAdded := now.Add(-time.Duration(si*9+2) * time.Hour)
		seriesItem := &model.Item{
			ID:             seriesID,
			Type:           model.TypeSeries,
			Name:           sd.title,
			SortName:       sd.title,
			Overview:       sd.overview,
			Year:           sd.year,
			PremiereDate:   fmt.Sprintf("%d-09-12T00:00:00.0000000Z", sd.year),
			Rating:         sd.rating,
			OfficialRating: "TV-14",
			Genres:         sd.genres,
			LibraryID:      ShowLibraryID,
			ParentID:       ShowLibraryID,
			AddedAt:        seriesAdded,
			ArtSeed:        "demo:" + sd.key,
			Demo:           true,
		}
		var latest time.Time
		for sn, season := range sd.seasons {
			seasonNum := sn + 1
			seasonID := id(fmt.Sprintf("demo:season:%s:%d", sd.key, seasonNum))
			seasonItem := &model.Item{
				ID:           seasonID,
				Type:         model.TypeSeason,
				Name:         fmt.Sprintf("Season %d", seasonNum),
				SortName:     fmt.Sprintf("%03d", seasonNum),
				Year:         sd.year,
				LibraryID:    ShowLibraryID,
				ParentID:     seriesID,
				SeriesID:     seriesID,
				SeriesName:   sd.title,
				SeasonNumber: seasonNum,
				ChildCount:   len(season.episodes),
				AddedAt:      seriesAdded,
				ArtSeed:      seriesItem.ArtSeed,
				Demo:         true,
			}
			items = append(items, seasonItem)
			for ei, ep := range season.episodes {
				epNum := ei + 1
				mi := mediaInfo()
				added := seriesAdded.Add(time.Duration(ei) * time.Minute * 7)
				if added.After(latest) {
					latest = added
				}
				items = append(items, &model.Item{
					ID:             id(fmt.Sprintf("demo:episode:%s:%d:%d", sd.key, seasonNum, epNum)),
					Type:           model.TypeEpisode,
					Name:           ep.title,
					SortName:       fmt.Sprintf("%02d%02d", seasonNum, epNum),
					Overview:       ep.overview,
					Year:           sd.year,
					PremiereDate:   fmt.Sprintf("%d-09-%02dT00:00:00.0000000Z", sd.year, 12+epNum),
					Rating:         sd.rating - 0.2 + float64(epNum%3)*0.1,
					OfficialRating: "TV-14",
					RuntimeTicks:   int64(ep.minutes) * 60 * 10_000_000,
					Genres:         sd.genres,
					LibraryID:      ShowLibraryID,
					ParentID:       seasonID,
					SeriesID:       seriesID,
					SeriesName:     sd.title,
					SeasonID:       seasonID,
					SeasonName:     seasonItem.Name,
					SeasonNumber:   seasonNum,
					EpisodeNumber:  epNum,
					Path:           "demo://sample",
					Container:      "mp4",
					Size:           int64(len(sampleBytes)),
					AddedAt:        added,
					Media:          mi,
					ArtSeed:        id(fmt.Sprintf("demo:art:%s:%d:%d", sd.key, seasonNum, epNum)),
					Demo:           true,
				})
			}
		}
		seriesItem.ChildCount = len(sd.seasons)
		if !latest.IsZero() {
			seriesItem.AddedAt = latest
		}
		items = append(items, seriesItem)
	}
	return items
}

func id(s string) string {
	sum := md5.Sum([]byte(s))
	return hex.EncodeToString(sum[:])
}
